async saveMediaAsset({ projectId, mediaAsset }: { projectId: string; mediaAsset: MediaAsset }): Promise<void> {
  const { mediaMetadataAdapter, mediaAssetsAdapter } = this.getProjectMediaAdapters({ projectId });
  const metadata: MediaAssetData = {
    id: mediaAsset.id,
    name: mediaAsset.name,
    type: mediaAsset.type,
    size: mediaAsset.file.size,
    width: mediaAsset.width,
    height: mediaAsset.height,
    thumbnailUrl: mediaAsset.thumbnailUrl,
  };

  try {
    await mediaAssetsAdapter.set({ key: mediaAsset.id, value: mediaAsset.file });
    await mediaMetadataAdapter.set({ key: mediaAsset.id, value: metadata });
  } catch (error) {
    try {
      await mediaAssetsAdapter.remove(mediaAsset.id); // Compensating rollback: clean up orphaned binary
    } catch {
      // Preserve original error
    }
    if (this.isQuotaExceededError({ error })) {
      throw new StorageQuotaExceededError({ requiredBytes: mediaAsset.file.size });
    }
    throw error;
  }
}

export class IndexedDBAdapter<T> implements StorageAdapter<T> {
  private dbName: string;
  private storeName: string;
  private version: number;

  private async getDB(): Promise<IDBDatabase> {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(this.dbName, this.version);
      request.onerror = () => reject(request.error);
      request.onsuccess = () => resolve(request.result);
      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result;
        if (!db.objectStoreNames.contains(this.storeName)) {
          db.createObjectStore(this.storeName, { keyPath: "id" });
        }
      };
    });
  }

  async set({ key, value }: { key: string; value: T }): Promise<void> {
    const db = await this.getDB();
    const transaction = db.transaction([this.storeName], "readwrite");
    const store = transaction.objectStore(this.storeName);
    return new Promise((resolve, reject) => {
      const request = store.put({ id: key, ...value });
      request.onerror = () => reject(request.error);
      request.onsuccess = () => resolve();
    });
  }
}

export interface ApiError {
  code: number;
  message: string;
  errors?: Record<string, string>;
  result: null;
}

export const formatErrorMessage = (error: unknown): string[] => {
  const axiosError = error as AxiosError<ApiError>;
  const apiError = axiosError.response?.data;

  if (!apiError) {
    return [axiosError.message || "An error occurred"];
  }

  // Jika terdapat error validasi field-specific
  if (apiError.errors && Object.keys(apiError.errors).length > 0) {
    return Object.values(apiError.errors);
  }

  // Jika terdapat pesan umum
  if (apiError.message) {
    const formattedMessage = apiError.message.charAt(0).toUpperCase() + apiError.message.slice(1);
    return [formattedMessage];
  }

  return ["An error occurred"];
};

export const showErrorToast = (error: AxiosError<ApiError>) => {
  const errors = formatErrorMessage(error);
  const errorList = errors.map(err => `• ${err}`).join('\n');

  toast.error("Error", {
    description: errorList,
    style: { whiteSpace: 'pre-line' }
  });
};

export const useEditorStore = create<EditorState>((set, get) => ({
  project: null,
  isLoading: true,
  error: null,
  selectedElementIds: [],
  mediaUrls: {},
  isPlaying: false,

  updateScene: (patch) => {
    const { project } = get();
    if (!project) return;
    const updated: TProject = {
      ...project,
      scenes: { ...project.scenes, ...patch, updatedAt: new Date() },
    };
    set({ project: updated });
    storageService.saveProject({ project: updated });
  },

  deleteSelectedElements: () => {
    const { project, selectedElementIds } = get();
    if (!project || selectedElementIds.length === 0) return;
    const selectedSet = new Set(selectedElementIds);
    const elements = project.scenes.tracks.elements.filter(
      (el) => !selectedSet.has(el.id),
    );
    const updated: TProject = {
      ...project,
      scenes: {
        ...project.scenes,
        tracks: { ...project.scenes.tracks, elements },
        updatedAt: new Date(),
      },
    };
    set({ project: updated, selectedElementIds: [] });
    storageService.saveProject({ project: updated });
  },
}));

